/** Lanes render in the order of the `lanes` array. A lane with no projects is hidden. */
export type LaneId = "paid" | "software" | "web";

export type Lane = {
  id: LaneId;
  label: string;
};

/**
 * hand     — I substantially wrote the implementation. AI may have answered questions/debugged.
 * assisted — AI substantially participated; I implemented/understand meaningful parts.
 * vibes    — Implementation substantially generated by an AI agent under my direction.
 */
export type AiInvolvement = "hand" | "assisted" | "vibes";

/**
 * Drives how the screenshot is framed.
 * phone   — portrait only, shown inside a device-shaped frame.
 * web     — landscape on wide screens, portrait (mobile screenshot) on narrow ones.
 * desktop — landscape only.
 */
export type MediaKind = "phone" | "web" | "desktop";

export type Media = {
  /**
   * Full-size path under /public, e.g. "/shots/raincal01.webp". `npm run shots` makes it,
   * plus the "_thumb" version shown on cards (raincal01_thumb.webp). Leave out for a placeholder.
   */
  landscape?: string;
  portrait?: string;
  alt?: string;
};

export type ExtraLink = {
  label: string;
  href: string;
};

export type Project = {
  /** Used as the URL hash (#raincal) and React key. Keep it unique and stable. */
  id: string;
  name: string;
  lane: LaneId;

  /** Shown on the collapsed card. One short line. */
  purpose: string;
  /** e.g. "iOS app", "Website", "Data pipeline + website" */
  artifact: string;
  ai: AiInvolvement;
  /** Shown on the card, e.g. "’26" or "’24–’26". Omit if unknown. */
  year?: string;

  skills: string[];
  /** Only when informative. */
  concepts?: string[];
  /** Only when there is something worth saying. */
  note?: string;

  links: {
    /** Repo URL, or "private" to say so without linking. Omit to show nothing. */
    github?: string | "private";
    live?: string;
    extra?: ExtraLink[];
  };

  kind: MediaKind;
  /** Screenshots. The first is the card image; the rest join it in the open card's gallery. */
  media?: Media[];
  /** Tint for the placeholder and the card's stage, 0–360. */
  hue: number;
};
